#!/usr/bin/env python3
"""Generate the C pose contract consumed by the freestanding PS firmware."""

import argparse
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import pose_contract as pc

OUT = os.path.join(ROOT, "sw", "ps_uart_print", "pose_contract.h")


def c_row(values):
    return "    {" + ", ".join(str(int(v)) for v in values) + "},"


def render():
    lines = [
        "/* Generated by tools/gen_pose_contract.py; do not edit manually. */",
        "#ifndef POSE_CONTRACT_H",
        "#define POSE_CONTRACT_H",
        "",
        "#define POSE_SCHEMA_V2 %du" % pc.POSE_SCHEMA_V2,
        "#define POSE_VALID_MASK 0x%06xu" % pc.POSE_VALID_MASK,
        "#define POSE_MODEL_CLASSES %du" % pc.POSE_MODEL_CLASSES,
        "#define POSE_MIN_CONF %du" % pc.POSE_MIN_CONF,
        "#define POSE_HOLD_CONF %du" % pc.POSE_HOLD_CONF,
        "#define POSE_CONFIRM_WINDOWS %du" % pc.POSE_CONFIRM_WINDOWS,
        "#define POSE_REST_WINDOWS %du" % pc.POSE_REST_WINDOWS,
        "#define POSE_UNCERTAIN_WINDOWS %du" % pc.POSE_UNCERTAIN_WINDOWS,
        "#define POSE_SMOOTH_MS %du" % pc.POSE_SMOOTH_MS,
        "#define POSE_STALE_MS %du" % pc.POSE_STALE_MS,
        "#define POSE_ANGLE_Q_SHIFT %du" % pc.POSE_ANGLE_Q_SHIFT,
        "#define POSE_ANGLE_Q_SCALE %du" % pc.POSE_ANGLE_Q_SCALE,
        "",
        "static const char *const pose_field_names[22] = {",
    ]
    for name in pc.POSE_FIELDS_V2:
        lines.append('    "%s",' % name)
    lines += [
        "};",
        "",
        "static const i32 pose_table[5][22] = {",
    ]
    for name in pc.POSE_NAMES:
        lines.append(c_row(pc.POSES_V2[name]))
    lines += [
        "};",
        "",
        "/* Define POSE_CONTRACT_INCLUDE_Q8 before including this header when",
        " * a binary transport or another fixed-point consumer needs it. */",
        "#ifdef POSE_CONTRACT_INCLUDE_Q8",
        "static const i32 pose_table_q8[5][22] = {",
    ]
    for name in pc.POSE_NAMES:
        lines.append(c_row(
            value * pc.POSE_ANGLE_Q_SCALE for value in pc.POSES_V2[name]))
    lines += [
        "};",
        "#endif",
        "",
        "#endif",
        "",
    ]
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--output", default=OUT)
    args = ap.parse_args()
    with open(args.output, "w", newline="\n") as fh:
        fh.write(render())
    print("generated %s" % os.path.relpath(args.output, ROOT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
